css:
:scope { width: min(100%, 1086px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 1 / span 24; grid-row: 1 / span 8; font-family: var(--os-font-heading); font-size: 59.2px; font-weight: 380; line-height: 1.08; letter-spacing: -0.015em; color: var(--os-color-text); }
.gx__i2 { grid-column: 1 / span 16; grid-row: 13 / span 13; font-family: var(--os-font-heading); font-size: 41.6px; font-weight: 380; line-height: 1.2; letter-spacing: -0.012em; color: var(--os-color-text); }
.gx__i3 { grid-column: 1 / span 16; grid-row: 30 / span 6; font-family: var(--os-font-heading); font-size: 41.6px; font-weight: 380; line-height: 1.2; letter-spacing: -0.012em; color: var(--os-color-text); }
.gx__i4 { grid-column: 1 / span 16; grid-row: 41 / span 19; font-family: var(--os-font-heading); font-size: 41.6px; font-weight: 380; line-height: 1.2; letter-spacing: -0.012em; color: var(--os-color-text); }
.gx__i5 { grid-column: 1 / span 16; grid-row: 64 / span 13; font-family: var(--os-font-heading); font-size: 41.6px; font-weight: 380; line-height: 1.2; letter-spacing: -0.012em; color: var(--os-color-text); }
.gx__i6 { grid-column: 1 / span 5; grid-row: 84 / span 8; font-family: var(--os-font-label); font-size: 15.2px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: inherit; }
.gx__i7 { grid-column: 7 / span 5; grid-row: 84 / span 5; font-family: var(--os-font-label); font-size: 15.2px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: inherit; }
.gx__i8 { grid-column: 13 / span 5; grid-row: 84 / span 3; font-family: var(--os-font-label); font-size: 15.2px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: inherit; }
.gx__i9 { grid-column: 1 / span 16; grid-row: 99 / span 19; font-family: var(--os-font-heading); font-size: 41.6px; font-weight: 380; line-height: 1.2; letter-spacing: -0.012em; color: var(--os-color-text); }
.gx__i10 { grid-column: 1 / span 14; grid-row: 130 / span 3; font-family: var(--os-font-label); font-size: 15.2px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: inherit; }
.gx__i11 { grid-column: 1 / span 14; grid-row: 140 / span 3; font-family: var(--os-font-label); font-size: 15.2px; font-weight: 400; line-height: 1.65; letter-spacing: 0em; color: inherit; }
.gx__i12 { grid-column: 1 / span 4; grid-row: 150 / span 6; font-family: var(--os-font-label); font-size: 16.3px; font-weight: 700; line-height: 1.1; letter-spacing: 0em; color: var(--os-color-text); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-heading); font-size: 47px; }
  .gx__i2 { font-family: var(--os-font-heading); font-size: 33px; }
  .gx__i3 { font-family: var(--os-font-heading); font-size: 33px; }
  .gx__i4 { font-family: var(--os-font-heading); font-size: 33px; }
  .gx__i5 { font-family: var(--os-font-heading); font-size: 33px; }
  .gx__i6 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i7 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i8 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i9 { font-family: var(--os-font-heading); font-size: 33px; }
  .gx__i10 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i11 { font-family: var(--os-font-label); font-size: 14px; }
  .gx__i12 { font-family: var(--os-font-label); font-size: 14px; }
}
